#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 15;

int n, m;
int a[N][N];

void sort_row(int n) {
    for (int i = 1; i <= m; i++)
        for (int j = 1; j < m; j++)
            if (a[n][j] > a[n][j + 1]) {
                int tmp = a[n][j];
                a[n][j] = a[n][j + 1];
                a[n][j + 1] = tmp;
            }
    return;
}

void sort_col(int m) {
    for (int i = 1; i <= n; i++)
        for (int j = 1; j < n; j++)
            if (a[j][m] > a[j + 1][m]) {
                int tmp = a[j][m];
                a[j][m] = a[j + 1][m];
                a[j + 1][m] = tmp;
            }
    return;
}

int main() {
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            scanf("%d", &a[i][j]);
    for (int i = 1; i <= n; i++)
        sort_row(i);
    for (int i = 1; i <= m; i++)
        sort_col(i);
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            printf("%d%c", a[i][j], " \n"[j == m]);
    return 0;
}
